G = ['1000110', '0100101', '0010011', '0001111']
m = '1011'
c = [0] * 7
for i, bit in enumerate(m):
    if bit == '1':
        for j in range(7):
            c[j] ^= int(G[i][j])
r = c[:]
r[3] ^= 1
H = ['1101100', '1011010', '0111001']
s = []
for row in H:
    total = 0
    for j, bit in enumerate(row):
        if bit == '1':
            total ^= r[j]
    s.append(total)
print(s[0])
print(s[1])
print(s[2])
